class MyStack {
    private final Queue<Integer> q = new ArrayDeque<>();   // the items, oldest at the front

    public void push(int x) {
        q.offer(x);                                        // O(1)
    }

    public int pop() {
        for (int i = 0; i < q.size() - 1; i++) {
            q.offer(q.poll());                             // rotate the older items behind the newest
        }
        return q.poll();                                   // the newest is now at the front
    }

    public int top() {
        for (int i = 0; i < q.size() - 1; i++) {
            q.offer(q.poll());                             // rotate the newest to the front...
        }
        int x = q.peek();
        q.offer(q.poll());                                 // ...and one more step puts the order back
        return x;
    }

    public boolean empty() {
        return q.isEmpty();
    }
